    # Calls:
    # 1 - (401) GET:/api/get_log
    # 2 - (200) GET:/api/get_log
    # 3 - (401) GET:/api/get_log
    # Found 1 potential fault of type-code 201
    @timeout_decorator.timeout(60)
    def test_45_get_on_get_log_vulnerableToXSS(self):
        
        headers = {}
        headers["content-type"] = "application/x-www-form-urlencoded"
        body = "username=pyload&password=pyload"
        cookies_pyload_jar = requests \
                .post(self.baseUrlOfSut + "/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False).cookies
        cookies_pyload = requests.utils.dict_from_cookiejar(cookies_pyload_jar)
        
        headers = {}
        headers["content-type"] = "application/x-www-form-urlencoded"
        body = "username=alice&password=alicepass"
        cookies_alice_jar = requests \
                .post(self.baseUrlOfSut + "/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False).cookies
        cookies_alice = requests.utils.dict_from_cookiejar(cookies_alice_jar)
        
        
        headers = {}
        headers['Accept'] = "application/json"
        res_0 = requests \
                .get(self.baseUrlOfSut + "/api/get_log?offset=6",
                    headers=headers, cookies=cookies_pyload, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 401
        assert "www-authenticate" not in res_0.headers
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["error"] == "Access denied"
        
        # Fault201. Cross-Site Scripting (XSS).
        headers = {}
        headers['Accept'] = "application/json"
        res_1 = requests \
                .get(self.baseUrlOfSut + "/api/get_log?offset=6",
                    headers=headers, cookies=cookies_alice, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_1.status_code == 200
        assert "application/json" in res_1.headers["content-type"]
        assert len(res_1.json()) == 4703
        assert res_1.json()[0] == "[2026-09-27 17:23:16]  DEBUG               pyload  ADDON UserAgentSwitcher: Setting maximum redirections to 10\n"
        assert res_1.json()[1] == "[2026-09-27 17:23:16]  DEBUG               pyload  ADDON UserAgentSwitcher: Use custom user-agent string `Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:87.0) Gecko/20100101 Firefox/87.0`\n"
        assert res_1.json()[2] == "[2026-09-27 17:23:16]  DEBUG               pyload  DOWNLOADER DefaultPlugin[342]: Plugin version: 0.52\n"
        # Skipping assertions on the remaining 4700 elements. This limit of 3 elements can be increased in the configurations
        
        headers = {}
        headers['Accept'] = "application/json"
        res_2 = requests \
                .get(self.baseUrlOfSut + "/api/get_log?offset=6",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_2.status_code == 401
        assert "www-authenticate" not in res_2.headers
        assert "application/json" in res_2.headers["content-type"]
        assert res_2.json()["error"] == "Invalid API credentials"


